class C{String s(boolean p,String[]g){int R=g.length,C=g[0].length(),q[]=new int[R*C],v[]=q.clone();long A=0;for(int r=R;r-->0;){var s=g[r];for(int c=0;c<C;c++){var h=s.charAt(c);if(h<48|h>57)continue;int b=c,n=0;for(;c<C&&(h=s.charAt(c))>47&h<58;c++)n=n*10+h-48;int o=0;for(int y=r+2;y-->r-1;)for(int x=c+1;x-->b-1;)if(y>=0&y<R&x>=0&x<C){h=g[y].charAt(x);if((h<48|h>57)&h!=46)o=1;if(h==42){int i=y*C+x;v[i]=q[i]++<1?n:v[i]*n;}}if(p&o>0)A+=n;c--;}}if(!p)for(int i=q.length;i-->0;)if(q[i]==2)A+=v[i];return A+"";}}
